-- ============================================================
-- 近代日本画家（テーマID: 15, category_id: 6）問題投入SQL
-- 全20問（難易度1〜3）
-- 選択肢対応: (ア)=0, (イ)=1, (ウ)=2, (エ)=3
-- ============================================================

INSERT INTO questions (category_id, theme_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty_level, is_premium) VALUES

(6, 15, '京都を拠点に活躍した近代日本画の巨匠で「班猫（はんびょう）」などの作品で知られる画家はだれか。', '上村松園', '竹内栖鳳', '西山翠嶂', '村上華岳', 1, '竹内栖鳳（たけうちせいほう、1864〜1942年）は京都を代表する近代日本画家です。写生を重視した確かな技術で動物画を得意とし、代表作「班猫」（1924年）は文化財にもなっています。文化勲章を受章した日本画の大家です。', 1, false),
(6, 15, '日本初の女性として文化勲章を受章した京都の日本画家はだれか。', '竹内栖鳳', '西山翠嶂', '上村松園', '山元春挙', 2, '上村松園（うえむらしょうえん、1875〜1949年）は京都出身の日本画家で、1948年に女性初の文化勲章を受章しました。美人画・人物画を得意とし、「序の舞」「焔」「晩秋」などが代表作です。', 1, false),
(6, 15, '竹内栖鳳が創設・運営に関わった京都の日本画団体はどれか。', '院展（日本美術院）', '国画創作協会', '竹杖会（ちくじょうかい）', '帝展', 2, '竹内栖鳳は「竹杖会（ちくじょうかい）」を主宰し、西山翠嶂・土田麦僊・村上華岳など多くの弟子を育てました。写生を基盤とした確かな技術で京都の近代日本画壇を牽引しました。', 2, false),
(6, 15, '竹内栖鳳の代表作「班猫」に描かれているものはどれか。', '虎', '縞猫（トラ猫）', '熊', '鷹', 1, '「班猫（はんびょう）」（1924年）は縞模様のある猫（トラ猫）を描いた作品で、毛並みの表現の精巧さが高く評価されています。重要文化財に指定されており、竹内栖鳳の代表作として最も知られた作品です。', 1, false),
(6, 15, '上村松園の代表作「序の舞（じょのまい）」に描かれているものはどれか。', '花と蝶', '能の舞姿をした女性', '富士山と松', '市場の女性たち', 1, '「序の舞」（1936年）は能の序の舞を舞う白拍子（しらびょうし）の女性を描いた作品で、松園の代表作として最も有名です。凛とした品格のある美人画で、重要文化財に指定されています。', 1, false),
(6, 15, '竹内栖鳳の弟子で「京都画壇の四天王」のひとりとされる画家はだれか。', '菊池芳文', '土田麦僊', '橋本関雪', '入江波光', 1, '土田麦僊（つちだばくせん、1887〜1936年）は竹内栖鳳に師事した後、国画創作協会の設立に参加した近代京都画壇を代表する画家です。女性像を中心に近代的な感覚の日本画を制作しました。', 2, false),
(6, 15, '村上華岳（むらかみかがく）が得意とした画題はどれか。', '風景画', '人物・仏教的主題', '花鳥画', '動物画', 1, '村上華岳（1888〜1939年）は仏教的な主題や人物画を独自の精神性で描いた画家です。「仏陀」「裸婦図」などが代表作で、東洋的な静謐さと宗教性が作品の特徴です。竹内栖鳳に学んだ後に独自の境地を開きました。', 2, false),
(6, 15, '京都市立芸術大学（旧・京都市立美術工芸学校）の前身となった学校が設立されたのはいつか。', '1880年（明治13年）', '1900年（明治33年）', '1920年（大正9年）', '1945年（昭和20年）', 0, '京都市立芸術大学の前身となる「京都府画学校」は1880年（明治13年）に設立され、日本最古の公立美術学校のひとつとされています。竹内栖鳳・上村松園らがここで学び、京都日本画壇の礎となりました。', 2, false),
(6, 15, '西山翠嶂（にしやますいしょう）が竹内栖鳳から受け継いだものはどれか。', '帝国美術院会員の地位', '青甲社（せいこうしゃ）の主宰', '国画創作協会の会長職', '院展の運営権', 1, '西山翠嶂（1879〜1958年）は竹内栖鳳の弟子で、師の主宰した「竹杖会」を継いで「青甲社（せいこうしゃ）」として引き継ぎ、京都画壇の中心的な存在となりました。文化勲章も受章しています。', 3, false),
(6, 15, '京都国立近代美術館（京都市左京区岡崎）が所蔵する近代日本画コレクションとして特に有名なのはどれか。', '浮世絵のコレクション', '京都画壇の作品群', '琳派の名品', '江戸時代の屏風絵', 1, '京都国立近代美術館は竹内栖鳳・上村松園・村上華岳ら京都画壇の作品を多数所蔵しており、近代京都日本画のコレクションとして著名です。工芸作品も含め京都の近代美術を総合的に収蔵しています。', 2, false),
(6, 15, '「国画創作協会」を竹内栖鳳の弟子たちが設立した主な理由はどれか。', '帝展（官展）の権威主義に対する反発', '西洋画の技法を取り入れるため', '外国への作品輸出のため', '政府の支援を受けるため', 0, '国画創作協会（1918年設立）は土田麦僊・村上華岳・榊原紫峰・野長瀬晩花らが、官展（帝展）の権威主義・保守性に反発して自由な表現を追求するために設立した美術団体です。', 3, false),
(6, 15, '橋本関雪（はしもとかんせつ）が京都市左京区に設けた邸宅・庭園の名称はどれか。', '無鄰菴', '白沙村荘（はくさそんそう）', '渉成園', '対龍山荘', 1, '橋本関雪（1883〜1945年）は京都市左京区銀閣寺道に「白沙村荘（はくさそんそう）」という邸宅・庭園を設け、現在も美術館として一般公開されています。中国画の影響を受けた豪放な作風が特徴の画家です。', 2, false),
(6, 15, '竹内栖鳳が渡欧し西洋美術を学んだ年はいつか。', '1899〜1900年', '1910〜1911年', '1920〜1921年', '1930〜1931年', 0, '竹内栖鳳は1900〜1901年（明治33〜34年）にパリ万博を機に渡欧し、印象派を中心とした西洋美術を直接学びました。帰国後はその経験を日本画に融合させ、写生主義を深化させた作品を多数発表しました。', 3, false),
(6, 15, '「鳥獣戯画」など古典絵画の模写で知られ、近代日本画の基礎を確立した画家として京都で活躍した人物はだれか。', '円山応挙', '狩野永徳', '長沢芦雪', '伊藤若冲', 0, '円山応挙（まるやまおうきょ、1733〜1795年）は江戸時代の画家ですが、写生を基盤とした円山派を創始し、竹内栖鳳ら近代京都画壇に大きな影響を与えました。厳密には近代画家ではありませんが、近代京都日本画の源流として重要です。', 3, false),
(6, 15, '上村松園の作品「焔（ほのお）」のテーマはどれか。', '能の演目「葵上」から取った嫉妬する女の霊', '秋の紅葉', '子育ての女性', '花火大会', 0, '「焔（ほのお）」（1918年）は源氏物語の「葵上（あおいのうえ）」を主題に、六条御息所の生き霊を表現した作品です。嫉妬に燃える女の怨念を鬼気迫る表現で描き、松園の作品の中でも異色の傑作として知られています。', 3, false),
(6, 15, '「琳派」の祖として知られ、近代京都画壇にも影響を与えた画家はだれか。', '俵屋宗達', '尾形光琳', '酒井抱一', '神坂雪佳', 0, '琳派の祖は俵屋宗達（たわらやそうたつ、江戸初期）とされています。宗達→光琳→抱一→鈴木其一と継承され、近代では神坂雪佳（かみさかせっか）らが京都で琳派を継承・発展させました。', 2, false),
(6, 15, '竹内栖鳳が受賞した日本芸術の最高位の称号はどれか。', '芸術院賞', '文化勲章', '内閣総理大臣賞', '帝国美術院会員', 1, '竹内栖鳳は1937年（昭和12年）に文化勲章を受章しました。日本画家として初期の文化勲章受章者のひとりであり、近代京都日本画壇の最高峰として評価されています。', 1, false),
(6, 15, '近代日本画の「日本美術院（院展）」を設立した人物はだれか。', '竹内栖鳳', '岡倉天心', '横山大観', '菱田春草', 1, '日本美術院（院展）は1898年（明治31年）に岡倉天心（おかくらてんしん）が設立しました。フェノロサと共に西洋化に対抗して日本画の伝統を守ることを目指し、横山大観・菱田春草らがここで活動しました。', 2, false),
(6, 15, '「四条派」とはどのような画派か。', '室町幕府が保護した官営の画派', '円山応挙の写生主義を継承した京都の画派', '中国宋元画を忠実に模倣した画派', '浮世絵師から転向した画家の集団', 1, '四条派は円山応挙の弟子・松村呉春（まつむらごしゅん）が京都四条に居を構えたことに由来します。応挙の写生主義に与謝蕪村の俳画的な軽やかさを加えた様式が特徴で、竹内栖鳳らに影響を与えました。', 3, false),
(6, 15, '現在の京都市立芸術大学が移転する予定の場所はどこか。', '宇治市', '京都駅東部（崇仁地区）', '嵐山地区', '亀岡市', 1, '京都市立芸術大学は長年西京区大枝に位置していましたが、2023年に京都駅東部・崇仁地区（下京区）への移転を完了しました。駅前の立地を活かして市内外との文化交流拠点としての役割が期待されています。', 2, false);

